<template>
  <div class="app">
    <div v-if="!authChecked" class="app-loading"></div>
    <site-password v-else-if="showGate" @verified="onVerified" />
    <template v-else>
      <open-page v-if="page===-1" @homePage="homePage"></open-page>
      <home-page v-if="page===0" @chosenNum="nextPage"></home-page>
      <text-page v-if="page===1" @back="back" :tabNum="chosenTab"></text-page>
    </template>
  </div>
</template>

<script>
import OpenPage from "@/components/OpenPage";
import HomePage from "@/components/HomePage";
import TextPage from "@/components/TextPage";
import SitePassword from "@/components/SitePassword";
import { supabase } from "@/supabase";

export default {
  name: "App",
  components: {
    HomePage,
    TextPage,
    OpenPage,
    SitePassword,
  },
  data() {
    return {
      page: -1,
      chosenTab: -1,
      authChecked: false,
      siteVerified: false,
      sitePasswordSet: false,
      adminSession: null,
    };
  },
  computed: {
    showGate() {
      return this.sitePasswordSet && !this.siteVerified && !this.adminSession;
    },
  },
  async mounted() {
    const [{ data: { session } }, { data: settingsData }] = await Promise.all([
      supabase.auth.getSession(),
      supabase.from('site_settings').select('value').eq('key', 'site_password_hash').maybeSingle(),
    ]);

    this.adminSession = session;
    this.sitePasswordSet = !!(settingsData && settingsData.value);
    this.siteVerified = sessionStorage.getItem('site_verified') === 'true';
    this.authChecked = true;

    supabase.auth.onAuthStateChange((event, session) => {
      this.adminSession = session;
    });
  },
  methods: {
    onVerified() {
      this.siteVerified = true;
    },
    nextPage(chosenNum) {
      this.chosenTab = chosenNum;
      this.page++;
    },
    back() {
      this.page = 0;
    },
    homePage() {
      this.page = 0;
    },
  },
};
</script>

